public sealed class OffloadPipeline
{
    private readonly Channel<string> _channel = Channel.CreateBounded<string>(
        new BoundedChannelOptions(256) { FullMode = BoundedChannelFullMode.Wait });

    public ValueTask QueueAsync(string payload, CancellationToken cancellationToken) =>
        _channel.Writer.WriteAsync(payload, cancellationToken);

    public async Task RunWorkerAsync(CancellationToken cancellationToken)
    {
        await foreach (var payload in _channel.Reader.ReadAllAsync(cancellationToken))
        {
            await PublishAsync(payload, cancellationToken);
        }
    }
}
